async function loadStatic(l){let entry=state.entries.get(l.id)||{features:[]};try{const b=await fetchJSON(l.url);if(b.type!=='FeatureCollection'||!Array.isArray(b.features))throw Error('GeoJSON 자료 형식 오류');const valid=b.features.filter(f=>validGeometry(f.geometry,{bounds:state.regionProfile.bounds}));entry={features:valid.map((f,i)=>({...f,properties:{...f.properties,id:String(f.properties?.id||f.id||l.id+'-'+i)}})),state:b.metadata?.state==='not-connected'?'not-connected':'loaded',metadata:b.metadata||{},title:l.title,loadedAt:new Date().toISOString(),rejected:b.features.length-valid.length};state.entries.set(l.id,entry);}catch(e){state.entries.set(l.id,{...entry,error:e.message});}drawData();}
async function loadSafetySnapshots(){
 let manifest;
 try{manifest=await fetchJSON('/data/city/safety/manifest.json');}catch{return;}
 const published=(manifest.datasets||[]).filter(item=>item.state==='published'&&LAYER_BY_ID[item.id]);
 await Promise.all(published.map(async item=>{
  try{
   const body=await fetchJSON('/data/city/safety/'+encodeURIComponent(item.id)+'.geojson');
   if(body.type!=='FeatureCollection'||body.metadata?.complete!==true||!Array.isArray(body.features))return;
   const accepted=body.features.filter(f=>validGeometry(f.geometry));
   state.entries.set(item.id,{features:accepted,state:'loaded',title:LAYER_BY_ID[item.id].title,loadedAt:body.metadata.collectedAt,metadata:body.metadata,rejected:body.features.length-accepted.length});
   if(item.id==='sd-cold'&&state.enabled.has('official-cold-shelter')){state.enabled.delete('official-cold-shelter');state.enabled.add(item.id);}
   if(item.id==='sd-heat'&&state.enabled.has('official-heat-shelter')){state.enabled.delete('official-heat-shelter');state.enabled.add(item.id);}
  }catch{}
 }));
 // Background snapshot arrival must never replace the user's selected map category.
 drawData();
}
async function loadAPI(id){if(!legacyEnabled(state.regionProfile)){toast('이 지역의 기존 API 연결은 검증 후 사용할 수 있습니다.');return;}const l=LAYER_BY_ID[id];if(!l?.api)return;if(!state.config?.configured[l.key]){toast(`${l.title}는 해당 API 키와 활용 승인이 필요합니다.`);showSettings();return;}
 const seq=(loadSequences.get(id)||0)+1;loadSequences.set(id,seq);const old=state.entries.get(id)||{features:[],title:l.title};state.entries.set(id,{...old,state:'loading',scanned:0,error:null});renderLayers();let page=1,all=[],seen=new Set(),scanned=0,total=null,last;
 try{while(page<=150){if(seq!==loadSequences.get(id))return;const b=await fetchJSON(`/api/city-data?kind=${id}&dong=all&page=${page}`);if(seq!==loadSequences.get(id))return;if(!b.geojson?.features)throw Error('GeoJSON 응답 없음');if(b.stale)throw Error('서버 갱신 실패 · 이전 정상 자료가 반환되었습니다.');const returned=b.geojson.features;const signature=returned.length?returned.map(f=>f.properties.id).join('|'):null;if(signature&&seen.has(signature))throw Error('동일 페이지 응답 반복');if(signature)seen.add(signature);scanned+=b.totalScanned||0;if(total!==null&&b.totalCount!==null&&total!==b.totalCount)throw Error('수집 도중 전체 건수가 변경되었습니다.');total=b.totalCount;all.push(...returned);last=b;state.entries.set(id,{...old,state:'loading',scanned,error:null});renderLayers();if(b.complete)break;if(!b.nextPage||b.nextPage<=page)throw Error('페이지 연속 정보 오류');page=b.nextPage;await new Promise(r=>setTimeout(r,120));}
 if(seq!==loadSequences.get(id))return;if(!last?.complete){state.entries.set(id,{...old,state:old.features.length?'loaded':'partial',features:old.features.length?old.features:all,error:'페이지 제한에 따른 부분수집',scanned,metadata:last});}
 else{const unique=[...new Map(all.map(f=>[f.properties.id,f])).values()];if(old.features.length&&!unique.length)throw Error('기존 자료가 있었으나 갱신 결과가 0건입니다. 기존 자료 유지');const accepted=unique.filter(f=>validGeometry(f.geometry));state.entries.set(id,{features:accepted,title:l.title,state:'loaded',loadedAt:last.collectedAt,metadata:last,rejected:unique.length-accepted.length});toast(`${l.title}: 서구 자료 ${accepted.length}개 반영`);}
 }catch(e){if(seq!==loadSequences.get(id))return;state.entries.set(id,{...old,state:old.features.length?'loaded':'unloaded',error:e.message});toast(`${l.title}: ${e.message}`);}drawData();}
async function toggleLayer(id,on){if(!legacyEnabled(state.regionProfile)&&id!==state.regionProfile.facilityLayerId&&!state.entries.has(id))return;if(!on&&state.selected?.layer===id){close();state.selected=null;state.isolate=false;}on?state.enabled.add(id):state.enabled.delete(id);state.isolate=false;state.activePreset=null;const l=layerConfig(id);if(l?.kind==='raster'){if(on&&!state.config?.configured[l.key]){state.enabled.delete(id);toast('이 지도층의 API 키 또는 서비스 설정이 필요합니다.');showSettings();}else view?.send({type:'raster',id,visible:on});}else if(on&&l?.manual){const entry=state.entries.get(id);if((entry?.state!=='loaded'&&!(id==='sd-icing'&&entry?.state==='partial'))||!['all',state.dong].includes(entry.metadata?.scopeDong)){state.enabled.delete(id);toast('이 재난안전 자료는 현재 구역의 수신 확인이 필요합니다. API 패널에서 조회하세요.');enhancements.action({dataset:{action:'safety-hub'}});}}else if(on&&l?.api&&state.entries.get(id)?.state!=='loaded')loadAPI(id);else if(on&&l?.url&&!state.entries.has(id))loadStatic(l);drawData();}
function preset(id){activeRequest++;byId('crumb-facility').textContent='';const p=PRESETS.find(p=>p.id===id);if(!p)return;if(id==='walk'){state.activePreset=id;renderLayers();api.run('walk-routes');return;}walkMap.clear();state.activePreset=id;state.enabled=new Set(id==='safety'?p.layers.map(layer=>layer==='official-cold-shelter'&&state.entries.get('sd-cold')?.state==='loaded'?'sd-cold':layer==='official-heat-shelter'&&state.entries.get('sd-heat')?.state==='loaded'?'sd-heat':layer):p.layers);state.isolate=false;state.selected=null;stopMedia();for(const l of LAYERS.filter(l=>l.kind==='raster'))view?.send({type:'raster',id:l.id,visible:false});drawData();if(id==='environment')showEnvironment();else if(id==='planning')showTools();else if(id==='safety')showSafety();else close();}
function findFeature(layer,id){return state.entries.get(layer)?.features.find(f=>String(f.properties.id||f.id)===String(id));}
const info=(pairs)=>`<dl class="info-grid">${pairs.map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v===null||v===undefined||v===''?'자료 없음':v)}</dd>`).join('')}</dl>`;
function selectFeature(layer,id,move=true){activeRequest++;const original=findFeature(layer,id),f=original&&filterFeatures([original],state.scope)[0];if(!f)return;state.selected={layer,id:String(id)};state.point=representative(f.geometry);stopMedia();byId('crumb-facility').textContent='› '+(f.properties.name||'선택 시설');if(move)requestAnimationFrame(()=>fly(f.geometry,'facility'));drawData();const p=f.properties,l=LAYER_BY_ID[layer]||{title:state.entries.get(layer)?.title};
 let extra=[];for(const[k,label]of Object.entries({capacity:'수용인원(등록)',area:'면적(등록)',temperature:'기온(℃)',humidity:'습도(%)',windSpeed:'풍속(m/s)',windDirection:'풍향(°)',rainfall:'강수(mm)',pm10:'PM10(㎍/㎥)',pm25:'PM2.5(㎍/㎥)',pm10Flag:'PM10 상태',pm25Flag:'PM2.5 상태',observedAt:'관측·등록 시각',forecastTime:'예보 시각',issuedAt:'예보 발표',scenarioTime:'그늘 시나리오 시간',height:'높이(m)',heightBasis:'높이 근거',shadowLength:'그림자 길이 근사(m)',reportedStatus:'원래 보고 상태',updateFailed:'최근 갱신 실패',lastSuccessfulAt:'마지막 수신 성공',statusLabel:'등록 상태',expiresAt:'상태 유효기한',phone:'대표전화',emergencyPhone:'응급실 전화',registeredBeds:'등록 병상 수',night:'야간개방 원자료',weekend:'주말개방 원자료',weekdayHours:'평일 운영 원자료',weekendHours:'휴일 운영 원자료',eventType:'돌발 유형',message:'안내 내용',sourceYear:'원자료 기준연도',accidentCount:'사고 건수',deaths:'사망자 수',reportedAt:'원자료 시각'}))if(p[k]!==undefined&&p[k]!==null)extra.push([label,p[k]]);
 if(p.originalAttributes)for(const [key,value]of Object.entries(p.originalAttributes))if(typeof value==='string'||typeof value==='number')extra.push(['원본 '+(p.originalFieldLabels?.[key]||key),value]);
 if(layer.startsWith('vw-')&&p.sourceAttributes)for(const [key,value]of Object.entries(p.sourceAttributes))if(typeof value==='string'||typeof value==='number')extra.push(['원본 '+key,value]);
 show(p.name||'선택 시설',`<span class="badge">${esc(l.title)}</span><span class="badge">${f.geometry.type==='Point'?'대표 위치':'제공 도형'}</span><div class="detail-actions"><button class="primary" data-action="feature-frame">가까이 보기</button><button class="secondary" data-action="isolate">${state.isolate?'다른 시설도 보기':'이 시설만 보기'}</button></div>${layer===(state.regionProfile?.facilityLayerId||'public-facilities')?`<button class="primary full" data-action="space-twin-from-feature" data-id="${esc(id)}">이 공간의 운영 대안 비교</button>`:''}${info([['선택 지역',label()],['주소',p.address],...extra,['자료 출처',p.sourceName],['자료 기준일',p.sourceDate],['반영 시각',p.collectedAt||state.entries.get(layer)?.loadedAt]])}<p class="note ${p.note?'warning':''}">${esc(p.geometryMeaning||p.note||l.note||'표시자료의 위치·운영 상태와 기준일을 확인하세요.')}</p>${p.sourceUrl?`<p class="small"><a href="${safeUrl(p.sourceUrl)}" target="_blank" rel="noopener noreferrer">원자료 보기 ↗</a></p>`:''}<div class="detail-actions"><button class="secondary" data-action="inspect-current">날씨 확인</button><button class="secondary" data-action="neighborhood">주변 인프라 500m</button>${layer==='heat'?'<button class="secondary" data-action="near-emergency">주변 응급의료 3km</button>':''}${layer==='cctv'?'<button class="primary" data-action="play-cctv">공개영상 보기</button>':''}${layer==='air-stations'?'<button class="primary" data-action="air-current">측정소 관측자료</button>':''}</div><div id="media-box"></div><p class="small">지도 위 포인트는 시설의 대표 위치입니다. 출입구·이용 가능 여부를 뜻하지 않습니다.</p>`,'feature');}
function safeUrl(s){try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?esc(u.href):'#';}catch{return '#';}}
function recordRows(fs){return fs.slice(0,150).map(f=>`<button class="record" data-action="feature" data-id="${esc(f.properties.id||f.id)}" data-layer="${esc(f._layer)}"><strong><i class="legend-dot" style="--cat:${LAYER_BY_ID[f._layer]?.color||'#cab694'}"></i>${esc(f.properties.name||'명칭 없음')}</strong><small>${esc(LAYER_BY_ID[f._layer]?.title||state.entries.get(f._layer)?.title||'사용자 자료')} · ${esc(f.properties.sourceDate||'기준일 없음')}</small></button>`).join('');}
function showList(query=''){state.listQuery=query;const fs=visible().filter(f=>!query||String(f.properties.name).includes(query));show(`${label()}의 표시자료`,`${info([['표시 항목',`${fs.length}개`],['집계 범위','선택한 동 × 켜진 정보층']])}<p class="note">위치·면·개별 공간은 집계 단위가 다릅니다. 같은 건물에 여러 회의실이 있을 수 있으므로 항목 수를 건물 수나 이용 수요로 해석하지 않습니다.</p><input id="list-query" class="search-input" placeholder="시설명 찾기" value="${esc(query)}"><div class="detail-actions"><button class="primary" data-action="export-csv">현재 목록 CSV</button><button class="secondary" data-action="import">자료 가져오기</button><button class="secondary" data-action="export-state">보기 조건 저장</button></div><div class="record-list">${recordRows(fs)||'<p class="note">표시할 항목이 없습니다. 연결 전·부분수집·실패 여부를 확인하세요.</p>'}</div>${fs.length>150?'<p class="small">화면 목록은 150개까지 표시합니다. CSV에는 현재 조건 전체가 포함됩니다.</p>':''}`,'list');}
function showSettings(){const names={tmap:'TMAP 생활도보길',vworld3d:'브이월드 3D 지도',vworldRest:'브이월드 주소·토지',safety:'무더위쉼터',emergency:'응급의료 기본정보',air:'에어코리아',weather:'기상청',safemap:'생활안전지도',floodmap:'도시침수지도'};show('지도·자료 연결',`<p>3D 건물은 <b>브이월드</b>에서, 시설·환경·도보 자료는 각 제공기관에서 불러옵니다.</p><div class="detail-actions"><button class="primary" data-action="engine" data-engine="vworld">실제 브이월드 3D</button><button class="secondary" data-action="engine" data-engine="clean">밝은 도시모형</button><button class="secondary" data-action="engine" data-engine="libre">OSM 경량지도</button><button class="secondary" data-action="engine" data-engine="boundary">경계도 · 3D 아님</button></div>${info(Object.entries(names).map(([k,v])=>[v,state.config?.configured[k]?'환경변수 설정됨':'설정 필요']))}<p class="note warning">설정됨은 인증·데이터 수신 성공이 아닙니다. 각 정보층을 켜서 실제 결과를 확인하세요.</p><label class="field-label"><input type="checkbox" id="focus-switch" ${state.focus?'checked':''}> 선택 구역 밖 지면 어둡게</label><p class="small">행정자료는 경계로 잘라 표시합니다. 브이월드 원본 건물을 동 경계로 삭제하는 기능은 아닙니다.</p><h3>갱신·추가</h3><div class="detail-actions"><button class="secondary" data-action="refresh-enabled">켜진 API 새로고침</button><button class="secondary" data-action="stop-load">수집 중지</button><button class="secondary" data-action="import">시설/도형 가져오기</button><button class="secondary" data-action="restore-state">보기 조건 불러오기</button></div><p class="small"><a href="/classic.html" target="_blank" rel="noopener">기존 v0.2 자료 검수·동별 통계·기간 비교 ↗</a></p><p class="small">환경변수 값은 Vercel에서 입력합니다. 이 화면에서 키를 수집하거나 저장하지 않습니다. 예제 파일 속 키를 재사용하지 마세요.</p>`,'settings');}
function showSafety(){show('안전·복지 시설',`<button class="primary full" data-action="safety-hub">재난안전 API 10종 연결 · 한파/무더위/민방위/결빙</button><p>선택 구역의 대피학교·쉼터·응급의료기관을 조회합니다.</p><div class="tool-grid">${['heat','emergency','shelter-schools'].map(id=>`<button data-action="add-layer" data-id="${id}">${icon(LAYER_BY_ID[id].icon)}${LAYER_BY_ID[id].title}</button>`).join('')}<button data-action="flood">${icon('water')}침수·홍수 지도</button></div><p class="note warning">응급의료기관의 위치·기본정보는 실시간 수용 가능 여부가 아닙니다. 긴급상황은 119를 우선하세요.</p><p class="small">좌표가 없는 공개 복지시설 22개 등의 주소 검수는 기존 자료 검수 화면에 보존했습니다.</p><a href="/classic.html" target="_blank" rel="noopener">주소 후보·복지시설 검수 열기 ↗</a>`,'safety');}
function showEnvironment(){show('환경을 함께 보기',`<button class="primary full" data-action="city-questions">폭염 대응시설·생활 질문으로 보기</button><p>선택 지점의 기상청 격자 실황과 실제 대기 측정소의 관측자료를 따로 확인합니다.</p><div class="tool-grid"><button data-action="tool" data-tool="inspect">${icon('pin')}지점 선택</button><button data-action="weather-center">${icon('sun')}이 동의 날씨</button><button data-action="add-layer" data-id="air-stations">${icon('wind')}대기 측정소</button><button data-action="model-import">${icon('layers')}분석결과 불러오기</button></div><p class="note">기상청 바람 방향은 해당 격자의 관측값입니다. 건물 사이 도시바람길·열섬·화재 확산을 계산한 결과가 아닙니다.</p><p class="small">별도 분석모형으로 만든 바람길·화재·침수 결과는 출처, 모형, 시나리오, 단위, 생성시각, 검증상태가 있는 GeoJSON으로 가져올 수 있습니다.</p>`,'environment');}
function showFlood(){show('침수·홍수 원자료',`<p>시나리오별 위험지도와 과거 침수흔적을 실제 3D 도시 위에 겹쳐 확인합니다.</p><div class="tool-grid">${['national-flood','local-flood','flood-trace','city-flood'].map(id=>`<button data-action="add-layer" data-id="${id}">${icon('water')}${LAYER_BY_ID[id].title}</button>`).join('')}</div><div class="detail-actions"><button class="primary" data-action="tool" data-tool="flood-point">지점 원자료 확인</button></div><p class="note warning">색이 있는 픽셀을 점수로 환산하거나 미수신·빈 이미지를 '안전'으로 판정하지 않습니다. 이 기능은 수위·침수심 예측 모델이 아닙니다.</p>`,'flood');}
function showTools(){show('도시 검토 도구',`<p>실제 지형을 살펴보고, 가상 배치안을 별도로 놓아 비교합니다.</p><div class="tool-grid"><button data-action="finish-check">적용·연결 점검</button><button data-action="editor-new">제설·공개시설 작성</button><button data-action="records">기록 보관함</button><button data-action="parcel">${icon('parcel')}필지·토지·건물</button><button data-action="tool" data-tool="slope">${icon('chart')}경사 표본 계산</button><button data-action="tool" data-tool="profile">${icon('chart')}지형단면 두 지점</button><button data-action="model">${icon('cube')}가상 GLB 배치</button><button data-action="tool" data-tool="hide-building">${icon('building')}건물 숨김</button><button data-action="restore-buildings">${icon('building')}건물 복구</button><button data-action="sun">${icon('sun')}시간·그림자</button><button data-action="flood">${icon('water')}침수지도</button><button data-action="report">${icon('download')}검토 기록</button><button data-action="clear-analysis">${icon('close')}표시 초기화</button></div><p class="note">지형 해상도와 SDK 제공 기능에 따라 실행 가능 여부가 달라집니다. 지형단면·경사 표본은 정밀 측량·지반 안정성·인허가 판정이 아닙니다.</p><button class="secondary full" data-action="model-import">외부 전문 분석결과 GeoJSON 가져오기</button>`,'tools');}
function showParcel(){show('필지·토지·건물 조회',`<p>서구의 지번주소를 검색한 뒤, 해당 필지의 토지특성·토지이용계획·용도별 건물 정보를 확인합니다.</p><input id="parcel-query" placeholder="예: 광주 서구 치평동 지번"><button class="primary full" data-action="parcel-search">서구 필지 검색</button><div id="parcel-results" class="record-list"></div><p class="note warning">조회한 건폐율·용적률은 기존 건물의 속성일 수 있습니다. 법정 허용 한도나 건축 가능 여부로 해석하지 않습니다.</p>`,'parcel');}
async function parcelSearch(){const token=++activeRequest;const q=byId('parcel-query')?.value||'';try{const b=await fetchJSON(`/api/city-data?kind=parcel-search&dong=${state.dong}&q=${encodeURIComponent(q)}`);if(token!==activeRequest||!byId('parcel-results'))return;byId('parcel-results').innerHTML=b.items.map(a=>`<button class="record" data-action="parcel-load" data-id="${a.pnu}"><strong>${esc(a.name)}</strong><small>반환된 필지 선택</small></button>`).join('')||'<p class="note">서구의 선택 범위에서 검색된 필지가 없습니다.</p>';}catch(e){toast(e.message);}}
const landLabels={lndcgrCodeNm:'지목',lndpclAr:'필지면적(㎡)',prposArea1Nm:'용도지역',tpgrphFrmCodeNm:'지형형상',roadSideCodeNm:'도로접면',pblntfPclnd:'공시지가(원/㎡)',lastUpdtDt:'자료 갱신일',cnflcAtNm:'저촉 원자료',prposAreaDstrcCodeNm:'용도지역지구',regstrSeCodeNm:'대장구분',mainPrposCodeNm:'주요용도',buldHg:'건물높이(m)',groundFloorCo:'지상층',undgrndFloorCo:'지하층',buldPlotAr:'대지면적(㎡)',buldBildngAr:'건축면적(㎡)',buldTotar:'연면적(㎡)',measrmtRt:'용적률(속성,%)',btlRt:'건폐율(속성,%)',strctCodeNm:'구조',useConfmDe:'사용승인일'};
async function parcelLoad(pnu){const token=++activeRequest;try{toast('필지와 속성자료를 확인하고 있습니다.');const b=await fetchJSON(`/api/city-data?kind=parcel&dong=${state.dong}&pnu=${pnu}`);if(token!==activeRequest)return;state.entries.set('parcel',{features:b.geojson.features,title:'선택 필지',state:'loaded'});state.enabled.add('parcel');drawData();fly(b.geojson.features[0].geometry,'facility');show('선택 필지 참고정보',`<p class="note warning">${esc(b.note)}</p>${Object.entries(b.data).map(([k,r])=>`<h3>${({land:'토지특성',use:'토지이용계획',building:'용도별 건물'})[k]} ${r.year?esc(r.year)+'년':''}</h3>${r.state!=='loaded'?'<p class="note">이 항목은 조회되지 않았습니다.</p>':r.items.map((item,i)=>`<div class="result-box"><strong>원자료 항목 ${i+1}</strong>${info(Object.entries(item).map(([k,v])=>[landLabels[k]||k,v]))}</div>`).join('')}`).join('')}<button class="secondary full" data-action="report">검토 기록</button>`,'parcel');state.results.push({...b,dong:state.dong,scopeName:label(),recordedAt:new Date().toISOString()});}catch(e){toast(e.message);}}
function showModel(){show('가상 건물 배치',`<p>내장형 GLB를 현재 브라우저에만 읽어 배치합니다. 브이월드에서는 실제 지형을, 도시모형에서는 높낮이가 없는 기준면을 사용합니다.</p><div class="detail-actions"><button class="primary" data-action="glb-select">1. GLB 선택</button><button class="secondary" data-action="tool" data-tool="place-model">2. 지도에서 위치 선택</button></div><label class="field-label">회전 <span id="heading-value">0°</span></label><input id="model-heading" type="range" min="0" max="360" value="0"><label class="field-label">배율 <span id="scale-value">1</span></label><input id="model-scale" type="range" min="0.1" max="5" step="0.1" value="1"><label class="field-label">지면에서 높이(m)</label><input id="model-height" type="number" min="-30" max="250" value="0"><div class="detail-actions"><button class="secondary" data-action="model-remove">배치안 제거</button><button class="secondary" data-action="tool" data-tool="hide-building">기존 건물 숨김</button><button class="secondary" data-action="restore-buildings">건물 복구</button></div><p class="note warning">25MB 이하, 외부 파일 참조 없는 GLB 2.0만 지원합니다. 배율 조정 후 크기는 설계 치수와 대조하세요. 기존 도시의 원본 건물은 삭제하지 않습니다.</p><div id="model-status"></div>`,'model');}
function showSun(){const kst=new Date(Date.now()+9*3600000).toISOString().slice(0,16);show('시간·그림자 참고',`<p>한국시간을 지정해 지도의 빛과 그림자를 살펴봅니다.</p><input id="sun-time" type="datetime-local" value="${kst}"><label class="field-label"><input id="sun-shadows" type="checkbox" checked> 그림자 표시</label><button class="primary full" data-action="sun-apply">화면에 적용</button><p class="note warning">날짜·시간 변경은 지도 조명에만 적용됩니다. 관측자료 시각은 바뀌지 않습니다. 일조시간·법정 일조권·열환경 분석 결과가 아닙니다.</p>`,'sun');}
function renderResult(m){if(m.error){toast(m.error);show('실행 결과 확인',`<p class="note warning">${esc(m.error)}</p><button class="secondary full" data-action="tools">분석 도구로 돌아가기</button>`,'result');return;}if(['model-loaded','model-placed'].includes(m.kind)){toast(m.note);if(byId('model-status'))byId('model-status').innerHTML=`<p class="note">${esc(m.note)}</p>`;return;}if(m.kind==='slope'){show('경사 표본 계산',`${info([['분석 지역',label()],['표본 간격',`${m.spacing}m`],['유효 높이',`${m.summary.validHeights} / ${m.summary.sampleCount}`],['유효 경사 셀',`${m.summary.validCells} / ${m.summary.totalCells}`],['평균 경사각',m.summary.meanDegrees?.toFixed(2)+'°'],['최대 경사각',m.summary.maxDegrees?.toFixed(2)+'°'],['조회 방식',m.method]])}<p class="note warning">${esc(m.note)}</p><button class="primary full" data-action="report">검토 기록 보기</button>`,'result');}else if(m.kind==='profile'){show('선택 선의 지형단면',`${profileChart(m.heights,m.length)}<label class="field-label">중앙 횡단면 길이(m)</label><input id="cross-length" type="number" min="10" max="1000" value="50"><button class="secondary full" data-action="cross-profile">중앙에서 수직 횡단면 계산</button>${info([['분석 길이',Math.round(m.length)+'m'],['유효 표본',`${m.heights.filter(Number.isFinite).length}/${m.heights.length}`],['조회 방식',m.method]])}<p class="note">${esc(m.note)}</p><button class="primary full" data-action="report">검토 기록 보기</button>`,'result');}else toast(m.note||'요청을 처리했습니다.');}
function profileChart(heights,length){const values=heights.filter(Number.isFinite);if(!values.length)return '<p>유효 표본이 없습니다.</p>';const min=Math.min(...values),max=Math.max(...values),range=Math.max(1,max-min);let parts=[],part=[];heights.forEach((v,i)=>{if(Number.isFinite(v))part.push(`${30+i/(heights.length-1)*245},${105-(v-min)/range*80}`);else if(part.length){parts.push(part);part=[];}});if(part.length)parts.push(part);return `<svg class="chart" viewBox="0 0 300 140" role="img" aria-label="지형 단면. 누락 표본은 선으로 연결하지 않음"><line x1="30" y1="105" x2="275" y2="105"/>${parts.map(p=>`<polyline points="${p.join(' ')}"/>`).join('')}<text x="2" y="30">${max.toFixed(0)}m</text><text x="2" y="105">${min.toFixed(0)}m</text><text x="30" y="125">0m</text><text x="240" y="125">${Math.round(length)}m</text></svg>`;}
async function inspectPoint(point){const token=++activeRequest;show('지점 정보 조회',`<p>주소·격자 실황·단기예보를 각각 조회하고 있습니다.</p>`,'point');
 const [address,weather,forecast]=await Promise.allSettled([fetchJSON(`/api/city-data?kind=reverse&dong=${state.dong}&lon=${point[0]}&lat=${point[1]}`),fetchJSON(`/api/weather?lon=${point[0]}&lat=${point[1]}`),fetchJSON(`/api/city-data?kind=forecast&dong=${state.dong}&lon=${point[0]}&lat=${point[1]}`)]);if(token!==activeRequest)return;
 const a=address.status==='fulfilled'?address.value:null,w=weather.status==='fulfilled'?weather.value:null,f=forecast.status==='fulfilled'?forecast.value:null;state.results.push({kind:'point',point,dong:state.dong,scopeName:label(),address:a,weather:w,forecast:f,recordedAt:new Date().toISOString()});
 show('선택 지점의 정보',`${info([['지역',label()],['경도 / 위도',point.map(v=>v.toFixed(6)).join(' / ')],...(a?.addresses||[]).map(r=>[r.type==='road'?'도로명주소':'지번주소',r.address])])}<h3>기상청 격자 실황</h3>${w?weatherHtml(w):'<p class="note warning">기상청 실황 응답을 확인하지 못했습니다. 미관측을 0으로 바꾸지 않습니다.</p>'}<h3>이후 단기예보</h3>${f?forecastHtml(f):'<p class="note warning">해당 발표시각의 예보를 확인하지 못했습니다.</p>'}<p class="small">좌표는 분석 기준점입니다. 격자 실황·예보는 개별 건물의 실측값이 아닙니다.</p><div class="detail-actions"><button class="secondary" data-action="flood">침수 원자료 확인</button><button class="secondary" data-action="report">검토 기록</button></div>`,'point');}
function forecastHtml(f){return `<p class="small">발표 ${esc(f.base.base_date)} ${esc(f.base.base_time)} · 격자 ${f.grid.nx}/${f.grid.ny}</p><div class="record-list">${f.rows.map(r=>`<div class="record"><strong>${esc(r.time.slice(4,6)+'/'+r.time.slice(6,8)+' '+r.time.slice(8,10)+':'+r.time.slice(10))}</strong><small>기온 ${r.temperature===null?'자료 없음':esc(r.temperature)+'℃'} · 강수확률 ${r.precipitationProbability===null?'자료 없음':esc(r.precipitationProbability)+'%'} · 풍속 ${r.windSpeed===null?'자료 없음':esc(r.windSpeed)+'m/s'}</small></div>`).join('')}</div><p class="small">${esc(f.note)}</p>`;}

function weatherHtml(w){const vals=w.values||w.observations||w.data||{};return info([['관측 기준',w.baseDate||w.base?.base_date||w.base_date],['관측 시각',w.baseTime||w.base?.base_time||w.base_time],['격자',w.grid?`${w.grid.nx??w.grid.x} / ${w.grid.ny??w.grid.y}`:'응답 확인'],...Object.entries(vals).filter(([k])=>['T1H','RN1','REH','WSD','VEC','PTY'].includes(k)).map(([k,v])=>[({T1H:'기온(℃)',RN1:'1시간 강수(mm)',REH:'습도(%)',WSD:'풍속(m/s)',VEC:'풍향(°)',PTY:'강수형태 코드'})[k],typeof v==='object'?v.value:v])]);}
async function inspectFlood(point){const token=++activeRequest;for(const u of floodImages)URL.revokeObjectURL(u);floodImages=[];show('지점의 침수지도 원본',`<p>네 종류의 지도 응답을 확인하고 있습니다.</p>`,'flood-point');const ls=LAYERS.filter(l=>['national-flood','local-flood','flood-trace','city-flood'].includes(l.id));const rs=await pointWmsImages(point,ls,state.dong);if(token!==activeRequest){rs.forEach(r=>r.image&&URL.revokeObjectURL(r.image));return;}floodImages=rs.map(r=>r.image).filter(Boolean);state.results.push({kind:'flood-evidence',point,dong:state.dong,scopeName:label(),layers:rs.map(({image,...r})=>r),recordedAt:new Date().toISOString()});show('지점의 침수지도 원본',`<p class="note warning">선택 지점 주변 약 40m × 40m의 제공기관 지도 이미지입니다. 별도의 위험점수·안전등급을 만들지 않습니다.</p>${rs.map(r=>`<div class="result-box"><strong>${esc(r.title)}</strong><p class="sample-caption">${esc(r.note)}</p>${r.image?`<div style="position:relative;width:128px"><img src="${r.image}" alt="${esc(r.title)} 원본 이미지"><span style="position:absolute;left:59px;top:54px;color:#111;text-shadow:0 0 2px white">＋</span></div>`:'<span class="badge">조회 미확인</span>'}</div>`).join('')}<button class="secondary full" data-action="report">근거 기록 확인</button>`,'flood-point');}
