async function importFile(file){if(!file)return;if(file.size>6*1024*1024)throw Error('자료 파일은 6MB 이하로 준비하세요.');const txt=await file.text();if(state.importMode==='state'){const s=JSON.parse(txt);if(!['0.3.0','0.4.0','0.4.1','0.5.0','0.6.0','0.6.1','0.7.0','0.8.0','0.8.1','0.9.0','0.10.0','0.11.0','0.12.0','0.12.1','0.12.2','0.13.0','0.14.0','0.15.0','0.15.1','0.16.0','0.17.0'].includes(s.version)||!state.dongs.some(f=>f.properties.dongId===s.dong)&&s.dong!=='all')throw Error('보기 조건 형식 오류');state.enabled=new Set(s.layers.filter(id=>!['events','cctv','flow','accidents'].includes(id)&&(LAYER_BY_ID[id]||state.entries.has(id))));state.focus=s.focus!==false;chooseDong(s.dong);return;}
 let raw;if(file.name.toLowerCase().endsWith('.csv')){const result=importFacilitiesCSV(txt);raw=result.accepted?fc(result.accepted):result.geojson||result;if(raw.type!=='FeatureCollection')throw Error(result.errors?.join('\n')||'CSV 양식을 확인하세요.');}else raw=JSON.parse(txt);
 if(raw.type!=='FeatureCollection'||!Array.isArray(raw.features)||raw.features.length>1500)throw Error('1500개 이하의 GeoJSON FeatureCollection을 사용하세요.');if(state.importMode==='model')modelResultValid(raw);
 const rejected=[];let fs=raw.features.filter((f,i)=>{const p=f.properties||{},okay=validGeometry(f.geometry)&&!!(p.sourceName||raw.metadata?.sourceName)&&!!(p.name||p.title);if(!okay)rejected.push(i+1);return okay;}).map((f,i)=>({...f,properties:{...f.properties,name:f.properties.name||f.properties.title,id:`import-${Date.now()}-${i}`,sourceName:f.properties.sourceName||raw.metadata.sourceName,sourceDate:f.properties.sourceDate||null,note:state.importMode==='model'?`외부 ${raw.metadata.modelName} / ${raw.metadata.scenario} / ${raw.metadata.validationStatus}`:f.properties.note||'사용자 제공자료 · 미검수'}}));
 const beforeClip=fs.length;fs=filterFeatures(fs,state.district);const outOfRegion=beforeClip-fs.length;if(!fs.length)throw Error('유효하고 출처가 있는 서구 자료가 없습니다.');const id=`import-${Date.now()}`;state.entries.set(id,{features:fs,state:'loaded',title:file.name,metadata:raw.metadata||{},loadedAt:new Date().toISOString()});state.enabled.add(id);state.activePreset=null;drawData();toast(`${fs.length}개 반영 · 형식 제외 ${rejected.length}개 · 구역 밖 ${outOfRegion}개. 브라우저 메모리에만 보관합니다.`);}
