async function refreshDecisionHome(){
 const target=byId('decision-home-result');if(!target||!state.regionProfile)return;
 const seq=++homeDecisionSequence;target.textContent='현재 자료로 시설 배치안을 계산하고 있어요.';
 try{const b=await fetchJSON('/api/decision-twin?region='+encodeURIComponent(state.regionProfile.id)+'&scope='+encodeURIComponent(state.dong||'all'));if(seq!==homeDecisionSequence)return;
  const r=b.result;target.replaceChildren();
  const strong=document.createElement('strong');strong.textContent=r.baseline?.uncovered===null?'이 지역의 연결 자료를 확인하세요.':`현재 거리조건 밖 대표위치 ${r.baseline.uncoveredLocations??r.baseline.uncovered}곳`;
  const small=document.createElement('span');small.textContent=r.scenario?.newlyCovered===null?'자료 범위와 기준일을 함께 보여드립니다.':`추가 후보 ${r.scenario?.proposedSites?.length||0}곳 → 새로 반경 안에 ${r.scenario?.newlyCoveredLocations??r.scenario?.newlyCovered??0}곳`;
  const detail=document.createElement('small');detail.textContent=`${r.preset?.title||'시설 배치 검토'} · 직선거리 ${r.parameters?.radiusM||r.preset?.radiusM||''}m 가정`;
  target.append(strong,small,detail);
 }catch{if(seq===homeDecisionSequence)target.textContent='시설 추가 · 점검 대상 · 후보지 비교를 시작해 보세요.';}
}
async function boot(){
 byId('overview-icon').innerHTML=icon('layers');byId('fullscreen-button').innerHTML=icon('expand');byId('settings-button').innerHTML=icon('settings');
 try{
  const requestedRegion=new URLSearchParams(location.search).get('region');
  const region=await fetchJSON('/api/region-profile'+(requestedRegion!==null?'?region='+encodeURIComponent(requestedRegion):''));state.regionProfile=validateRegionProfile(region.profile);
  const [boundaries,facilities]=await Promise.all([fetchJSON(state.regionProfile.boundaryUrl),fetchJSON(state.regionProfile.facilitiesUrl)]);
  state.regionReport={...validateRegionDataPack({profile:state.regionProfile,boundaries,facilities}),coverage:facilities.metadata?.coverage||null,facilitySourceDate:facilities.metadata?.sourceDate||null};
  state.dongs=boundaries.features.map((f,i)=>({...f,properties:{...f.properties,color:PALETTE[i%PALETTE.length]}}));
  state.district=unionGeometry(state.dongs);state.scope=state.district;applyRegionChrome(state.regionProfile);
  try{state.config=regionMapConfig(state.regionProfile,await fetchJSON('/api/city-config'));}catch{state.config={configured:{},note:'설정 API 조회 실패'};}
  if(!legacyEnabled(state.regionProfile)){state.enabled=new Set([state.regionProfile.facilityLayerId]);state.activePreset=null;}
  for(const [id,enabled]of Object.entries(state.config.configured||{}))if(id.startsWith('infra-')&&enabled&&LAYER_BY_ID[id]){LAYER_BY_ID[id].api=true;LAYER_BY_ID[id].key=id;}
  renderRegions();renderLayers();residentUi.ready();refreshDecisionHome();liveStatus=createLiveStatus({state,fetchJSON,label,show});liveStatus.refresh();
  await engine(initialMapEngine(state.regionProfile,location.search));homePanel.sync();
  await Promise.all(regionLayers(state.regionProfile,LAYERS).filter(l=>l.url).map(l=>loadStatic(l)));
  if(legacyEnabled(state.regionProfile))await loadSafetySnapshots();liveStatus.render();
  const work=new URLSearchParams(location.search).get('work');
  if(['shade','winter','safety','care','inspection'].includes(work)&&new URLSearchParams(location.search).get('tool')==='walk')await api.run('walk-routes',{mode:work});
  else if(['care','safety'].includes(work))await api.run('decision-living-map',{topic:work});
 }catch(e){residentUi?.ready(true);byId('start-message').textContent='지역 자료 연결을 확인하고 다시 시작해 주세요.';byId('start-card').hidden=false;}
}
